/**
 * Map API - 非遗地图接口
 * 
 * 接口列表:
 * - getPoints: 获取所有地图点位
 * - getPointDetail: 获取单个点位详情
 * - getRegions: 获取地区统计
 */

import request from './request.js'

export default {
  /**
   * 获取所有地图点位
   * @param {object} params - 查询参数 { type, region }
   */
  getPoints(params = {}) {
    return request.get('/map/points', { params })
  },

  /**
   * 获取单个点位详情
   * @param {string} id - 点位ID
   */
  getPointDetail(id) {
    return request.get(`/map/points/${id}`)
  },

  /**
   * 获取地区统计
   */
  getRegions() {
    return request.get('/map/regions')
  }
}
